from email.utils import parseaddr

ALLOWED_TOOLS = {"search_kb", "summarize_ticket", "send_email"}
INTERNAL_DOMAINS = {"example.com"}
NEEDS_APPROVAL = {"send_email"}

def authorize_tool_call(user, call):
    """Validate a tool call proposed by the LLM before it runs."""
    name, args = call["name"], call["arguments"]
    if name not in ALLOWED_TOOLS:
        return deny("tool not allowlisted", user, call)
    if not user.has_permission(name):        # the user's rights, not the model's
        return deny("user lacks permission", user, call)
    if name == "send_email":
        domain = parseaddr(args.get("to", ""))[1].rpartition("@")[2].lower()
        if domain not in INTERNAL_DOMAINS:
            return deny("external recipient", user, call)
    if name in NEEDS_APPROVAL:
        return queue_for_human_approval(user, call)
    return allow(user, call)

